        if (!dl) { console.error('[sdd] 행 동작 대상 목록 없음: dlt_docPageList'); return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: fn_viewOtherForm (인자 미해석) · document.getElementById('${doc.acptNo}'+'_0_otherForm').style.display = 'none'; (EL 미해석) · fn_Disclsviewer( '${doc.acptNo}'No }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }' ); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.langTpCd}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }' ); (EL 미해석) · fn_goWrite( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.langTpCd}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${fn:replace(doc.comEngAbbrv, '\'', '\\'') }' ); (EL 미해석) · fn_register( '${doc.acptNo}', '${doc.formCd}', '${doc.formVer}', '${doc.currFormVer}', '${doc.currEngFormVer}', '${doc.oldFormVerUseYn}', '${doc.langTpCd}', '${doc.formUpclssCd}' ,'${doc.rsnClssCd}','${doc.modOrgnDisclsAcptNo}','${doc.inqOrgnDisclsAcptNo}','${doc.engOrgnDisclsAcptNo}','${doc.modAddSeq}','${doc.applFormYn}' ,'${doc.ldMktTpCd }','${doc.disclsAcptTpCd}','${doc.subcomDisclsYn }','${doc.disclsObjCorpIsurCd }','${doc.disclsObjCorpIsurNm }','${doc.disclsObjCorpFssUnqNo }','${doc.disclsObjRepIsuSrtCd }','${doc.formCdExmpt}',${doc.formVerExmpt},'${fn:replace(doc.comEngAbbrv, '\'', '\\'') }', '${doc.reqObjAcptDocNo}' ); (EL 미해석) */

