/**
 * @method
 * @name scwin.progress_bar
 * @author Inswave
 * @date 2026. 09. 29
 * @param display
 * @returns
 * @hidden N
*/
scwin.progress_bar = function (display) {
    /* sdd-asis-lifecycle:begin progress_bar — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const on = (display === undefined || display === 'block' || display === true);
    const cu = $c.util.getComponent('progress_bar_curtain');
    const pb = $c.util.getComponent('prg_processing');
    if (on) {
        if (cu && cu.show) {
            cu.setStyle("display", "");
        }
        if (pb && pb.show) {
            pb.setStyle("display", "");
        }
    } else {
        if (cu && cu.hide) {
            cu.setStyle("display", "none");
        }
        if (pb && pb.hide) {
            pb.setStyle("display", "none");
        }
    }
    /* sdd-asis-lifecycle:end */
};



